<script setup lang="ts">
import {computed,ref,onMounted,onBeforeUnmount,watch,h} from 'vue';
import {theme,Modal,message} from 'ant-design-vue';
import {CloudServerOutlined,DashboardOutlined,TeamOutlined,GiftOutlined,NotificationOutlined,CameraOutlined,UserOutlined,HistoryOutlined,SettingOutlined,FolderOutlined,CodeOutlined,DatabaseOutlined,ScheduleOutlined,ReloadOutlined,PoweroffOutlined,PlayCircleOutlined,PauseCircleOutlined,SearchOutlined,MenuOutlined,BulbOutlined,LogoutOutlined,UploadOutlined,PlusOutlined,FileTextOutlined,ArrowLeftOutlined} from '@ant-design/icons-vue';
import {api,query,setCsrf,uploadFile} from './api';
import CardPanel from './CardPanel.vue';
import CodeEditor from './CodeEditor.vue';
import TerminalView from './TerminalView.vue';
import LegacyWorkspace from './LegacyWorkspace.vue';
import CommandInput from './CommandInput.vue';

const session=ref<any>(null),loginBusy=ref(false),initializing=ref(true),loginError=ref('');const loginForm=ref({username:'',password:''});
const page=ref('instances'),instance=ref(''),tab=ref('terminal'),search=ref(''),drawer=ref(false),loading=ref(false);
const dark=ref(localStorage.getItem('breakline-theme')==='dark'),sidebar=ref(localStorage.getItem('breakline-layout')==='left');
const overview=ref<any>({servers:[],host:{}}),error=ref(''),stamp=ref(0),command=ref(''),commandBusy=ref(false),commandHistory=ref<string[]>([]);
const owner=computed(()=>session.value?.user?.roles?.includes('owner'));
const menus=computed(()=>[
 {key:'instances',label:'实例管理',icon:CloudServerOutlined},{key:'overview',label:'总览',icon:DashboardOutlined},
 {key:'online',label:'在线玩家',icon:TeamOutlined},{key:'players',label:'玩家列表',icon:UserOutlined},
 {key:'grants',label:'物品与补偿',icon:GiftOutlined},{key:'moderation',label:'广播与玩家管理',icon:NotificationOutlined},
 {key:'evidence',label:'截图证据',icon:CameraOutlined},...(owner.value?[{key:'admins',label:'管理员',icon:UserOutlined}]:[]),
 {key:'audit',label:'操作记录',icon:HistoryOutlined},{key:'settings',label:'设置',icon:SettingOutlined}]);
const legacyPages=['online','players','grants','moderation','evidence','admins','audit','console'];
const isLegacy=computed(()=>legacyPages.includes(page.value));
const current=computed(()=>overview.value.servers.find((r:any)=>r.id===instance.value));
const servers=computed(()=>overview.value.servers.filter((r:any)=>(r.name+' '+r.id).toLowerCase().includes(search.value.toLowerCase())));
const liveCount=computed(()=>overview.value.servers.filter((r:any)=>r.status==='online').length);
const unknownCount=computed(()=>overview.value.servers.filter((r:any)=>r.status==='unknown').length);
const onlineCount=computed(()=>unknownCount.value?'—':overview.value.servers.reduce((sum:number,r:any)=>sum+(r.online??0),0));
function statusText(row:any){return row?.status==='online'?'运行中':row?.status==='stopped'?'已停止':'状态未知';}
const title=computed(()=>page.value==='instance'?(current.value?.name||'实例控制台'):menus.value.find(m=>m.key===page.value)?.label||'执行台');
const themeConfig=computed(()=>({algorithm:dark.value?theme.darkAlgorithm:theme.defaultAlgorithm,token:{colorPrimary:'#1677ff',borderRadius:6,fontSize:14,fontSizeLG:14,fontSizeSM:12,fontSizeXL:18}}));
const columns=[{title:'实例名称',key:'name'},{title:'状态',key:'status'},{title:'在线玩家',dataIndex:'online',key:'online'},{title:'内存',key:'memory'},{title:'操作',key:'actions',width:260}];
function size(n?:number|null){if(n===undefined||n===null)return '—';if(n<1024)return n+' B';const u=['KiB','MiB','GiB','TiB'];let v=n/1024,i=0;while(v>=1024&&i<3){v/=1024;i++;}return v.toFixed(1)+' '+u[i];}
function date(n:number){return new Date(n*1000).toLocaleString('zh-CN');}
function percent(used?:number,total?:number){return total?Math.min(100,Math.round((used||0)*100/total)):0;}
async function guarded(fn:()=>Promise<any>){error.value='';try{return await fn();}catch(e:any){error.value=e.message;message.error(e.message);}}
function go(key:string){page.value=key;drawer.value=false;error.value='';window.location.hash=key;}
async function login(){if(loginBusy.value)return;loginBusy.value=true;loginError.value='';try{const value=await api('login',loginForm.value);session.value=value;setCsrf(value.csrf);loginForm.value.password='';await refresh();}catch(e:any){loginError.value=e.message;}finally{loginBusy.value=false;}}
async function logout(){await guarded(()=>api('logout',{}));location.reload();}
async function refresh(){if(isLegacy.value&&(window as any).breaklineLegacy){await guarded(()=>(window as any).breaklineLegacy.page(page.value));return;}if(!session.value||loading.value)return;loading.value=true;try{overview.value=owner.value?await api('instance/overview'):{servers:(await api('servers')).servers,host:{}};stamp.value=Date.now();}catch(e:any){error.value=e.message;}finally{loading.value=false;}}
function open(row:any){instance.value=row.id;tab.value='terminal';cwd.value='';go('instance');}
async function operate(kind:string,values:any,after?:()=>Promise<any>){
 const op=await api('prepare',{kind,...values,reason:values.reason||'管理员通过实例管理执行'});
 return confirmOperation(op,after);
}
async function confirmOperation(op:any,after?:()=>Promise<any>){
 return new Promise<void>((resolve,reject)=>{Modal.confirm({title:'确认管理操作',content:op.summary,okText:'确认执行',cancelText:'取消',width:520,
  onOk:async()=>{try{const receipt=await api('confirm',{operationId:op.operationId});message.success(receipt.message||'操作已完成');await after?.();resolve();}catch(e:any){error.value=e.message+' · 操作号 '+op.operationId;message.error(error.value);reject(e);throw e;}},
  onCancel:async()=>{await api('cancel',{operationId:op.operationId}).catch(()=>{});resolve();}});});
}
async function lifecycle(row:any,action:string){await guarded(()=>operate('server.lifecycle',{server:row.id,action},refresh));}
async function sendCommand(){if(!command.value.trim()||commandBusy.value)return;const text=command.value.trim();commandBusy.value=true;await guarded(async()=>{if(text==='list'||text==='在线人数'){const result=await api('console-read',{server:instance.value,command:text});Modal.info({title:'指令回执',content:result.output});}else await operate('console',{server:instance.value,command:text,reason:'面板控制台'});commandHistory.value.push(text);command.value='';});commandBusy.value=false;}


const cwd=ref(''),files=ref<any[]>([]),fileBusy=ref(false),fileSearch=ref(''),editor=ref(false),editPath=ref(''),editText=ref(''),editHash=ref<string|null>(null),editNew=ref(false);
const fileColumns=[{title:'名称',key:'name'},{title:'大小',key:'size',width:120},{title:'修改时间',key:'modified',width:190},{title:'操作',key:'actions',width:245}];
const visibleFiles=computed(()=>files.value.filter(f=>f.name.toLowerCase().includes(fileSearch.value.toLowerCase())));
async function loadFiles(){fileBusy.value=true;await guarded(async()=>{const value=await api(query('instance/files',{server:instance.value,path:cwd.value}));files.value=value.entries;});fileBusy.value=false;}
async function folder(path:string){cwd.value=path;await loadFiles();}
function up(){void folder(cwd.value.split('/').slice(0,-1).join('/'));}
function pathFor(name:string){return [cwd.value,name].filter(Boolean).join('/');}
async function editFile(row:any){await guarded(async()=>{const value=await api(query('instance/file',{server:instance.value,path:row.path}));editPath.value=row.path;editHash.value=value.hash;editText.value=value.text;editNew.value=false;editor.value=true;});}
function newFile(){editPath.value=pathFor('new-file.txt');editText.value='';editHash.value=null;editNew.value=true;editor.value=true;}
async function saveFile(){await guarded(()=>operate('instance.file.write',{server:instance.value,path:editPath.value,text:editText.value,hash:editHash.value},async()=>{editor.value=false;await loadFiles();}));}
async function download(row:any){const a=document.createElement('a');a.href='/api/panel/'+query('instance/download',{server:instance.value,path:row.path});a.download=row.name;a.click();}
const nameDialog=ref(false),nameKind=ref('mkdir'),nameValue=ref(''),nameRow=ref<any>(null);
function askName(kind:string,row?:any){nameKind.value=kind;nameRow.value=row;nameValue.value=row?.name||'';nameDialog.value=true;}
async function named(){const values:any={server:instance.value,path:pathFor(nameValue.value)};if(nameKind.value==='rename'){values.path=nameRow.value.path;values.target=pathFor(nameValue.value);}await guarded(()=>operate('instance.file.'+nameKind.value,values,async()=>{nameDialog.value=false;await loadFiles();}));}
async function deleteFile(row:any){await guarded(()=>operate('instance.file.delete',{server:instance.value,path:row.path},loadFiles));}
const trashDialog=ref(false),trashEntries=ref<any[]>([]);
async function showTrash(){await guarded(async()=>{trashEntries.value=(await api(query('instance/trash',{server:instance.value}))).entries;trashDialog.value=true;});}
async function restoreTrash(row:any){await guarded(()=>operate('instance.file.restore',{server:instance.value,trash:row.id},async()=>{await showTrash();await loadFiles();}));}
const uploadInput=ref<HTMLInputElement>(),uploadBusy=ref(false);
async function upload(event:Event){const input=event.target as HTMLInputElement;const file=input.files?.[0];if(!file||uploadBusy.value)return;if(file.size>512*1024*1024){message.error('单文件上传上限为 512 MiB');input.value='';return;}uploadBusy.value=true;await guarded(async()=>{const op=await uploadFile(instance.value,pathFor(file.name),file);await confirmOperation(op,loadFiles);});uploadBusy.value=false;input.value='';}


const config=ref<any>({values:{},hash:null});
const configLabels:Record<string,string>={'motd':'服务器描述','max-players':'最大玩家数','view-distance':'视距','simulation-distance':'模拟距离','difficulty':'游戏难度','pvp':'玩家伤害','white-list':'白名单','spawn-protection':'出生点保护','allow-flight':'允许飞行'};
async function loadConfig(){await guarded(async()=>{config.value=await api(query('instance/config',{server:instance.value}));});}
async function saveConfig(){await guarded(()=>operate('instance.config',{server:instance.value,...config.value},loadConfig));}
const backups=ref<any[]>([]),tasks=ref<any[]>([]),taskDialog=ref(false);
const taskForm=ref({name:'',action:'save',content:'',interval:0,nextRun:new Date(Date.now()+300000).toISOString().slice(0,16)});
async function loadBackups(){await guarded(async()=>{backups.value=(await api(query('instance/backups',{server:instance.value}))).backups;});}
async function backupAction(action:string,row?:any){await guarded(()=>operate('instance.backup.'+action,{server:instance.value,...(row?{backup:row.id}:{})},loadBackups));}
async function loadTasks(){await guarded(async()=>{tasks.value=(await api(query('instance/tasks',{server:instance.value}))).tasks;});}
function newTask(){taskForm.value={name:'',action:'save',content:'',interval:0,nextRun:new Date(Date.now()+300000-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16)};taskDialog.value=true;}
async function createTask(){await guarded(()=>operate('instance.task.create',{server:instance.value,...taskForm.value,interval:Number(taskForm.value.interval)*60,nextRun:Math.floor(new Date(taskForm.value.nextRun).getTime()/1000)},async()=>{taskDialog.value=false;await loadTasks();}));}
async function removeTask(row:any){await guarded(()=>operate('instance.task.delete',{server:instance.value,task:row.id},loadTasks));}
watch([tab,instance],()=>{error.value='';if(page.value!=='instance')return;if(tab.value==='files')void loadFiles();if(tab.value==='config')void loadConfig();if(tab.value==='backups')void loadBackups();if(tab.value==='tasks')void loadTasks();});
watch(dark,v=>{localStorage.setItem('breakline-theme',v?'dark':'light');document.body.className=v?'app-dark-theme':'app-light-theme';},{immediate:true});
watch(sidebar,v=>localStorage.setItem('breakline-layout',v?'left':'top'));
let refreshTimer:ReturnType<typeof setInterval>;
onMounted(async()=>{try{session.value=await api('session');setCsrf(session.value.csrf);await refresh();const initial=location.hash.slice(1);if(menus.value.some(m=>m.key===initial))page.value=initial;}catch{session.value=null;}finally{initializing.value=false;}
 refreshTimer=setInterval(()=>{if(!document.hidden&&session.value&&!isLegacy.value&&page.value!=='settings')void refresh();},10000);
 window.addEventListener('breakline:session-expired',()=>{session.value=null;});
});
onBeforeUnmount(()=>clearInterval(refreshTimer));
</script>

<template>
 <a-config-provider :theme="themeConfig">
  <div v-if="initializing" class="initial-loading"><a-spin size="large"/></div>
  <div v-else-if="!session" class="login-workspace">
   <div class="login-brand">BREAKLINE <span>断界行动</span></div>
   <CardPanel title="登录管理面板"><a-form layout="vertical" :model="loginForm" @finish="login"><a-form-item name="username" label="账号"><a-input v-model:value="loginForm.username" autocomplete="username" size="large" required/></a-form-item><a-form-item name="password" label="密码"><a-input-password v-model:value="loginForm.password" autocomplete="current-password" size="large" required/></a-form-item><a-alert v-if="loginError" :message="loginError" type="error" show-icon/><a-button type="primary" html-type="submit" size="large" block :loading="loginBusy">登录</a-button></a-form><p class="login-note">断界行动 · 服务器管理</p></CardPanel>
  </div>
  <div v-else class="workspace" :class="{'sidebar-layout':sidebar}">
   <aside v-if="sidebar" class="app-sidebar"><div class="brand" @click="go('instances')">BREAKLINE<span>服务器管理</span></div><a-menu :selectedKeys="[page==='instance'?'instances':page]" mode="inline" theme="dark" @click="({key}:any)=>go(String(key))"><a-menu-item v-for="m in menus" :key="m.key"><template #icon><component aria-hidden="true" :is="m.icon"/></template>{{m.label}}</a-menu-item></a-menu><div class="sidebar-user"><a-avatar size="small"><UserOutlined aria-hidden="true"/></a-avatar><span>{{session.user.username}}</span><a-button type="text" @click="logout"><LogoutOutlined aria-hidden="true"/></a-button></div></aside>
   <header class="app-header-wrapper"><div class="app-header-content"><div class="header-left"><a-button class="mobile-menu" type="text" @click="drawer=true"><MenuOutlined aria-hidden="true"/></a-button><div class="brand" @click="go('instances')">BREAKLINE</div><nav class="desktop-nav"><button v-for="m in menus.slice(0,6)" :key="m.key" class="nav-button" :class="{'nav-button-active':page===m.key||page==='instance'&&m.key==='instances'}" @click="go(m.key)">{{m.label}}</button><a-dropdown><button class="nav-button">更多</button><template #overlay><a-menu @click="({key}:any)=>go(String(key))"><a-menu-item v-for="m in menus.slice(6)" :key="m.key">{{m.label}}</a-menu-item></a-menu></template></a-dropdown></nav></div><a-space class="header-tools"><a-button type="text" aria-label="切换主题" @click="dark=!dark"><BulbOutlined aria-hidden="true"/></a-button><a-dropdown><a-button type="text"><UserOutlined aria-hidden="true"/><span class="user-label">{{session.user.username}}</span></a-button><template #overlay><a-menu><a-menu-item @click="go('settings')">面板设置</a-menu-item><a-menu-item @click="logout">退出登录</a-menu-item></a-menu></template></a-dropdown></a-space></div></header>
   <a-drawer v-model:open="drawer" placement="left" title="断界行动" width="260"><a-menu :selectedKeys="[page]" mode="inline" @click="({key}:any)=>go(String(key))"><a-menu-item v-for="m in menus" :key="m.key"><template #icon><component aria-hidden="true" :is="m.icon"/></template>{{m.label}}</a-menu-item></a-menu></a-drawer>
   <main class="main-content"><div class="breadcrumbs"><span @click="go('instances')">控制面板</span><span>/</span><span v-if="page==='instance'" @click="go('instances')">实例管理 / </span><strong>{{title}}</strong><div class="breadcrumb-tools"><span class="updated" v-if="stamp">更新于 {{new Date(stamp).toLocaleTimeString('zh-CN')}}</span><a-button size="small" :loading="loading" @click="refresh"><ReloadOutlined aria-hidden="true"/>刷新</a-button></div></div>
    <a-alert v-if="error" class="error-banner" :message="error" type="error" show-icon closable @close="error=''"/>
    <section v-show="page==='instances'" class="main-layout-container">
     <div class="stat-strip"><CardPanel><a-statistic title="实例总数" :value="overview.servers.length"><template #prefix><CloudServerOutlined aria-hidden="true"/></template></a-statistic></CardPanel><CardPanel><a-statistic title="正在运行" :value="liveCount" :value-style="{color:'#52c41a'}"/></CardPanel><CardPanel><a-statistic title="在线玩家" :value="onlineCount"/></CardPanel><CardPanel><a-statistic title="未知状态" :value="unknownCount"/></CardPanel></div>
     <CardPanel title="实例管理"><template #operator><a-space><a-input v-model:value="search" placeholder="搜索实例" allow-clear class="instance-search"><template #prefix><SearchOutlined aria-hidden="true"/></template></a-input><a-button @click="refresh"><ReloadOutlined aria-hidden="true"/></a-button></a-space></template><a-table :data-source="servers" :columns="columns" row-key="id" :pagination="false" :scroll="{x:780}" :loading="loading"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><a href="#" class="instance-name" @click.prevent="open(record)"><CloudServerOutlined aria-hidden="true"/>{{record.name}}</a><div class="subtle">{{record.type||'Minecraft Java / Forge'}} · {{record.id}}</div></template><template v-else-if="column.key==='status'"><a-tag :color="record.status==='online'?'success':'default'">{{statusText(record)}}</a-tag></template><template v-else-if="column.key==='online'">{{record.online??'—'}}</template><template v-else-if="column.key==='memory'">{{size(record.process?.memory)}}</template><template v-else-if="column.key==='actions'"><a-space wrap><a-button type="primary" size="small" @click="open(record)">管理</a-button><template v-if="owner"><a-button size="small" @click="lifecycle(record,'start')"><PlayCircleOutlined aria-hidden="true"/>启动</a-button><a-button size="small" danger @click="lifecycle(record,'stop')"><PauseCircleOutlined aria-hidden="true"/>停止</a-button></template></a-space></template></template></a-table></CardPanel>
    </section>
    <section v-if="page==='overview'" class="main-layout-container overview-grid">
     <CardPanel title="主机信息"><a-descriptions :column="1" size="small"><a-descriptions-item label="CPU 核心">{{overview.host?.cpuCount??'—'}}</a-descriptions-item><a-descriptions-item label="系统负载">{{overview.host?.load?.map((n:number)=>n.toFixed(2)).join(' / ')||'暂无采样'}}</a-descriptions-item><a-descriptions-item label="实例">{{overview.servers.length}} 个 / {{liveCount}} 个运行中</a-descriptions-item><a-descriptions-item label="面板用户">{{session.user.username}} · {{owner?'服主':'管理员'}}</a-descriptions-item></a-descriptions></CardPanel>
     <CardPanel title="内存使用"><div class="resource-value">{{size(overview.host?.memory?.used)}} <span>/ {{size(overview.host?.memory?.total)}}</span></div><a-progress :percent="percent(overview.host?.memory?.used,overview.host?.memory?.total)" :show-info="!!overview.host?.memory"/><a-empty v-if="!overview.host?.memory" :image="undefined" description="主机尚无内存采样"/></CardPanel>
     <CardPanel title="数据磁盘"><div class="resource-value">{{size(overview.host?.disk?.used)}} <span>/ {{size(overview.host?.disk?.total)}}</span></div><a-progress :percent="percent(overview.host?.disk?.used,overview.host?.disk?.total)"/><p class="subtle">可用 {{size(overview.host?.disk?.free)}}</p></CardPanel>
     <CardPanel title="实例状态" class="full-width"><div class="overview-instances"><div v-for="row in overview.servers" :key="row.id" class="instance-tile" @click="open(row)"><CloudServerOutlined aria-hidden="true"/><h3>{{row.name}}</h3><a-badge :status="row.status==='online'?'success':'default'" :text="statusText(row)"/><p>在线 {{row.online??'未知'}} · 内存 {{size(row.process?.memory)}}</p><a-button block>进入控制台</a-button></div></div></CardPanel>
    </section>
    <section v-if="page==='instance'" class="main-layout-container">
     <CardPanel class="instance-heading"><div class="instance-title-row"><div><a-button type="text" @click="go('instances')"><ArrowLeftOutlined aria-hidden="true"/></a-button><CloudServerOutlined aria-hidden="true"/><strong>{{current?.name||instance}}</strong><a-tag :color="current?.status==='online'?'success':'default'">{{statusText(current)}}</a-tag></div><a-space wrap v-if="owner"><a-button @click="lifecycle(current,'start')"><PlayCircleOutlined aria-hidden="true"/>启动</a-button><a-button @click="lifecycle(current,'restart')"><ReloadOutlined aria-hidden="true"/>重启</a-button><a-button danger @click="lifecycle(current,'stop')"><PauseCircleOutlined aria-hidden="true"/>停止</a-button><a-dropdown><a-button>更多操作</a-button><template #overlay><a-menu><a-menu-item danger @click="lifecycle(current,'force_stop')">强制关闭</a-menu-item><a-menu-item danger @click="lifecycle(current,'force_restart')">强制重启</a-menu-item></a-menu></template></a-dropdown></a-space></div><a-tabs v-model:active-key="tab"><a-tab-pane key="terminal"><template #tab><CodeOutlined aria-hidden="true"/>控制台</template></a-tab-pane><a-tab-pane key="files" :disabled="!owner"><template #tab><FolderOutlined aria-hidden="true"/>文件管理</template></a-tab-pane><a-tab-pane key="config" :disabled="!owner"><template #tab><SettingOutlined aria-hidden="true"/>实例设置</template></a-tab-pane><a-tab-pane key="backups" :disabled="!owner"><template #tab><DatabaseOutlined aria-hidden="true"/>备份管理</template></a-tab-pane><a-tab-pane key="tasks" :disabled="!owner"><template #tab><ScheduleOutlined aria-hidden="true"/>计划任务</template></a-tab-pane></a-tabs></CardPanel>
     <div v-if="tab==='terminal'" class="terminal-grid"><CardPanel title="终端"><template #operator><a-tag>Minecraft Java</a-tag></template><TerminalView v-if="owner" :server="instance" :active="page==='instance'&&tab==='terminal'"/><a-result v-else status="403" title="终端仅服主可用" sub-title="玩家管理与广播入口仍可正常使用。"/><form v-if="owner" class="command-line" @submit.prevent="sendCommand"><CommandInput v-model="command" :server="instance" :history="commandHistory" @submit="sendCommand"/><a-button type="primary" html-type="submit" :loading="commandBusy">发送</a-button></form><a-space class="terminal-shortcuts" wrap v-if="owner"><a-button size="small" @click="command='list';sendCommand()">在线人数</a-button><a-button size="small" @click="command='save';sendCommand()">保存世界</a-button><a-button size="small" @click="command='announce '">发送公告</a-button><a-button size="small" @click="go('console')">指令指南</a-button></a-space></CardPanel><div class="instance-side"><CardPanel title="实例信息"><a-descriptions :column="1" size="small"><a-descriptions-item label="实例标识">{{instance}}</a-descriptions-item><a-descriptions-item label="玩家在线">{{current?.online??'未知'}}</a-descriptions-item><a-descriptions-item label="进程状态">{{current?.process?.state??'未知'}}</a-descriptions-item><a-descriptions-item label="进程内存">{{size(current?.process?.memory)}}</a-descriptions-item><a-descriptions-item label="CPU 时间">{{current?.process?.cpuSeconds===null||current?.process?.cpuSeconds===undefined?'—':current.process.cpuSeconds.toFixed(1)+' s'}}</a-descriptions-item></a-descriptions></CardPanel><CardPanel title="快捷入口"><div class="quick-links"><a-button @click="tab='files'"><FolderOutlined aria-hidden="true"/>文件管理</a-button><a-button @click="go('online')"><TeamOutlined aria-hidden="true"/>在线玩家</a-button><a-button @click="go('players')"><UserOutlined aria-hidden="true"/>玩家资产</a-button><a-button @click="go('evidence')"><CameraOutlined aria-hidden="true"/>截图证据</a-button></div></CardPanel></div></div>
     <CardPanel v-else-if="tab==='files'" title="文件管理"><template #operator><a-space wrap><a-button @click="up" :disabled="!cwd"><ArrowLeftOutlined aria-hidden="true"/>上一级</a-button><a-button @click="newFile"><FileTextOutlined aria-hidden="true"/>新建文件</a-button><a-button @click="askName('mkdir')"><PlusOutlined aria-hidden="true"/>新建目录</a-button><a-button type="primary" :loading="uploadBusy" @click="uploadInput?.click()"><UploadOutlined aria-hidden="true"/>上传文件</a-button><a-button @click="showTrash">回收区</a-button><a-button @click="loadFiles"><ReloadOutlined aria-hidden="true"/></a-button></a-space></template><input ref="uploadInput" type="file" hidden @change="upload"><div class="file-path"><a-input :value="cwd||'/'" aria-label="当前文件路径" readonly/><a-input v-model:value="fileSearch" placeholder="搜索当前目录" allow-clear/></div><a-table :data-source="visibleFiles" :columns="fileColumns" row-key="path" :loading="fileBusy" :pagination="{pageSize:30}" :scroll="{x:720}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><a href="#" @click.prevent="record.directory?folder(record.path):editFile(record)"><FolderOutlined aria-hidden="true" v-if="record.directory"/><FileTextOutlined aria-hidden="true" v-else/> {{record.name}}</a></template><template v-if="column.key==='size'">{{record.directory?'文件夹':size(record.size)}}</template><template v-if="column.key==='modified'">{{date(record.modified)}}</template><template v-if="column.key==='actions'"><a-space><a href="#" v-if="!record.directory" @click.prevent="editFile(record)">编辑</a><a href="#" v-if="!record.directory" @click.prevent="download(record)">下载</a><a href="#" @click.prevent="askName('rename',record)">重命名</a><a href="#" class="danger-text" @click.prevent="deleteFile(record)">删除</a></a-space></template></template></a-table><p class="subtle">上传上限 512 MiB，文本编辑上限 8 MiB；下载采用流式传输。目录删除与恢复需先停止实例。</p></CardPanel>
     <CardPanel v-else-if="tab==='config'" title="实例设置"><a-alert type="info" show-icon message="修改后保存，重启实例后生效。"/><a-form layout="vertical" class="config-form"><a-form-item v-for="(label,key) in configLabels" :key="key" :label="label"><a-select v-if="['pvp','white-list','allow-flight'].includes(String(key))" v-model:value="config.values[key]" :options="[{value:'true',label:'开启'},{value:'false',label:'关闭'}]"/><a-select v-else-if="key==='difficulty'" v-model:value="config.values[key]" :options="['peaceful','easy','normal','hard'].map(value=>({value,label:value}))"/><a-input v-else v-model:value="config.values[key]"/></a-form-item><div class="full-width"><a-button type="primary" @click="saveConfig">保存配置</a-button></div></a-form></CardPanel>
     <CardPanel v-else-if="tab==='backups'" title="备份管理"><template #operator><a-button type="primary" @click="backupAction('create')"><PlusOutlined aria-hidden="true"/>创建世界备份</a-button></template><a-alert type="info" show-icon message="创建与恢复世界备份前，请先正常停止实例。恢复前的世界会保留回滚副本。"/><a-table :data-source="backups" row-key="id" :pagination="{pageSize:10}" :scroll="{x:650}" :columns="[{title:'备份编号',dataIndex:'id'},{title:'大小',key:'size'},{title:'创建时间',key:'modified'},{title:'操作',key:'actions'}]"><template #bodyCell="{column,record}"><template v-if="column.key==='size'">{{size(record.size)}}</template><template v-if="column.key==='modified'">{{date(record.modified)}}</template><template v-if="column.key==='actions'"><a-space><a href="#" @click.prevent="backupAction('restore',record)">恢复</a><a href="#" class="danger-text" @click.prevent="backupAction('delete',record)">删除</a></a-space></template></template></a-table></CardPanel>
     <CardPanel v-else-if="tab==='tasks'" title="计划任务"><template #operator><a-button type="primary" @click="newTask"><PlusOutlined aria-hidden="true"/>创建任务</a-button></template><a-table :data-source="tasks" row-key="id" :pagination="{pageSize:10}" :scroll="{x:700}" :columns="[{title:'任务名称',dataIndex:'name'},{title:'动作',dataIndex:'action'},{title:'执行时间',key:'time'},{title:'状态',key:'status'},{title:'操作',key:'actions'}]"><template #bodyCell="{column,record}"><template v-if="column.key==='time'">{{date(record.next_run)}}<div class="subtle">{{record.interval?'每 '+record.interval/60+' 分钟':'仅执行一次'}}</div></template><template v-if="column.key==='status'"><a-tag :color="record.status==='SUCCESS'?'success':record.status==='WAITING'?'processing':'default'">{{record.status}}</a-tag><div class="subtle">{{record.result&&JSON.parse(record.result).message}}</div></template><template v-if="column.key==='actions'"><a href="#" class="danger-text" @click.prevent="removeTask(record)">删除</a></template></template></a-table></CardPanel>
    </section>
    <LegacyWorkspace v-if="session" v-show="isLegacy" :page="isLegacy?page:'players'" :active="isLegacy" :session="session" @navigate="value=>{if(legacyPages.includes(value))page=value}"/>
    <section v-if="page==='settings'" class="main-layout-container"><CardPanel title="面板设置"><a-form layout="vertical" class="settings-form"><a-form-item label="界面主题"><a-radio-group :value="dark?'dark':'light'" @change="(e:any)=>dark=e.target.value==='dark'"><a-radio-button value="light">浅色</a-radio-button><a-radio-button value="dark">深色</a-radio-button></a-radio-group></a-form-item><a-form-item label="导航布局"><a-radio-group :value="sidebar?'left':'top'" @change="(e:any)=>sidebar=e.target.value==='left'"><a-radio-button value="top">顶部导航</a-radio-button><a-radio-button value="left">侧边导航</a-radio-button></a-radio-group></a-form-item><a-form-item label="当前账号">{{session.user.username}} · {{owner?'服主':'管理员'}}</a-form-item><a-button danger @click="logout"><LogoutOutlined aria-hidden="true"/>退出登录</a-button></a-form><a-divider/><p class="subtle">界面部分组件及配色基于 MCSManager（Apache-2.0）改造。<a href="/mcsm/MCSManager-LICENSE.txt" target="_blank" rel="noopener">开源许可</a></p></CardPanel></section>
    <footer class="workspace-footer">断界行动 · 管理面板 <span>Breakline Operations</span></footer>
   </main>
   <a-modal v-model:open="editor" :title="editNew?'新建文件':'编辑文件'" width="900px" :mask-closable="false" :destroy-on-close="true" @ok="saveFile" ok-text="保存文件" cancel-text="关闭"><a-input v-model:value="editPath" :readonly="!editNew" class="editor-path" aria-label="编辑文件路径"/><CodeEditor v-model="editText" :path="editPath" :dark="dark" @save="saveFile"/></a-modal>
   <a-modal v-model:open="trashDialog" title="回收区" width="760px" :footer="null"><a-table :data-source="trashEntries" row-key="id" :columns="[{title:'原路径',dataIndex:'path'},{title:'删除时间',key:'time'},{title:'操作',key:'actions'}]"><template #bodyCell="{column,record}"><template v-if="column.key==='time'">{{date(record.deletedAt)}}</template><template v-if="column.key==='actions'"><a href="#" @click.prevent="restoreTrash(record)">恢复到原路径</a></template></template></a-table></a-modal>
   <a-modal v-model:open="nameDialog" :title="nameKind==='mkdir'?'新建目录':'重命名'" @ok="named" ok-text="继续" cancel-text="取消"><a-input v-model:value="nameValue" aria-label="文件或目录名称" placeholder="输入名称" @pressEnter="named"/></a-modal>
   <a-modal v-model:open="taskDialog" title="创建计划任务" @ok="createTask" ok-text="预览任务" cancel-text="取消"><a-form layout="vertical"><a-form-item label="名称"><a-input v-model:value="taskForm.name"/></a-form-item><a-form-item label="任务动作"><a-select v-model:value="taskForm.action" :options="[{value:'save',label:'保存世界'},{value:'announce',label:'发送公告'},{value:'start',label:'启动实例'},{value:'stop',label:'停止实例（空服检查）'},{value:'restart',label:'重启实例（空服检查）'},{value:'backup',label:'世界备份（实例停止后）'}]"/></a-form-item><a-form-item v-if="taskForm.action==='announce'" label="公告内容"><a-input v-model:value="taskForm.content"/></a-form-item><a-form-item label="首次执行时间"><input type="datetime-local" v-model="taskForm.nextRun" class="native-datetime"/></a-form-item><a-form-item label="重复间隔（分钟，0 为仅一次）"><a-input-number v-model:value="taskForm.interval" :min="0" :max="525600"/></a-form-item></a-form></a-modal>
  </div>
 </a-config-provider>
</template>
